const PLANS: &[Plan] = &[
    Plan { label: "roast chicken", names: &[Phrase { text: "roast chicken", words: &["roast", "chicken"] }, Phrase { text: "whole chicken", words: &["whole", "chicken"] }, Phrase { text: "the chicken", words: &["the", "chicken"] }, Phrase { text: "a chicken", words: &["a", "chicken"] }, Phrase { text: "chicken", words: &["chicken"] }], avoid: &["pox", "shop", "shops", "wing", "wings", "nugget", "nuggets", "soup", "stock", "sandwich", "salad", "curry", "pie", "breast", "breasts", "thigh", "thighs", "leg", "legs", "fillet", "fillets"], time: "20 minutes per 500g plus 20 minutes on top: 40 minutes per kilo, so 1 hour 40 for a 2kg bird.", temp: "190C, or 170C in a fan oven, in the middle of the oven.", done: "74C in the thickest part of the thigh on a digital thermometer, pushed in without touching bone, and the juices run clear with the leg moving freely in the socket; 75C for a moment is the same thing.", keep: "Wrap the leftovers within an hour and they keep 3 days in the fridge; the carcass makes good stock.", ahead: "You can get it ready the day before: rub it with butter and salt, keep it covered in the fridge, and roast it from cold with 10 minutes extra.", rest: "15 minutes under foil before carving, or the juice ends up on the board instead of in the meat.", skin: "Leave the skin on: it crisps and keeps the breast moist. Only take it off if someone at the table wants skinless, and expect the breast to dry a little.", stuffing: "Stuff the neck end only, weigh the bird with the stuffing in and add 15 to 20 minutes; check the stuffing is piping hot in the middle, not just the meat.", frosting: "", fill: "Push a lemon and a few garlic cloves into the cavity, rub the skin with butter and salt, and put onion and carrot in the tin under the bird for the gravy." },
    Plan { label: "chicken thigh", names: &[Phrase { text: "chicken thigh", words: &["chicken", "thigh"] }, Phrase { text: "chicken thighs", words: &["chicken", "thighs"] }, Phrase { text: "thighs", words: &["thighs"] }, Phrase { text: "traybake", words: &["traybake"] }, Phrase { text: "tray bake", words: &["tray", "bake"] }], avoid: &[], time: "35 to 40 minutes at 200C (180C fan), skin side up.", temp: "200C, or 180C in a fan oven, and the tray on a high shelf.", done: "The skin is crisp and the juices run clear when you pierce the thickest part; 74C with a thermometer.", keep: "They keep 3 days in the fridge and reheat better than breast.", ahead: "You can marinate them the night before, or roast them in the morning and reheat at 180C for 10 minutes.", rest: "5 minutes on the tray under foil is plenty: they are small, so there is no need to rest them like a whole bird.", skin: "Keep the skin on and salt it: it is the best part, and it protects the meat underneath. Skinless thighs need only 25 to 30 minutes.", stuffing: "", frosting: "", fill: "Marinate them in yoghurt with paprika, cumin and garlic for an hour if you can, or just oil, salt and lemon: they take strong flavours and stay juicy." },
    Plan { label: "chicken breast", names: &[Phrase { text: "chicken breast", words: &["chicken", "breast"] }, Phrase { text: "chicken breasts", words: &["chicken", "breasts"] }, Phrase { text: "breast", words: &["breast"] }], avoid: &[], time: "18 to 20 minutes at 200C (180C fan) for a flattened breast, and 12 to 15 for a small one.", temp: "200C, or 180C in a fan oven.", done: "The middle is white with no pink, and a thermometer reads 74C; take them out the moment they are there.", keep: "They keep 3 days, and are better sliced cold in a salad than reheated.", ahead: "Season them and keep them covered in the fridge a few hours before, or cook them in the morning and slice them cold: reheated they dry out.", rest: "5 minutes under foil, so the juice stays in when you cut them.", skin: "", stuffing: "", frosting: "", fill: "Salt it, then a herb butter or a spoon of pesto under the skin-side: breast is the one cut that needs help to stay moist." },
    Plan { label: "salmon", names: &[Phrase { text: "salmon", words: &["salmon"] }, Phrase { text: "salmon fillet", words: &["salmon", "fillet"] }, Phrase { text: "salmon fillets", words: &["salmon", "fillets"] }], avoid: &[], time: "12 to 15 minutes at 200C (180C fan), or 4 minutes skin side down in a hot pan.", temp: "200C, or 180C in a fan oven.", done: "The flesh just flakes when you press it with a fork, and it is still slightly translucent in the very middle.", keep: "Cooked salmon keeps 2 days in the fridge, and does not freeze well.", ahead: "You can bake it cold the night before and flake it into a salad or pasta.", rest: "No need to rest it: serve salmon straight away, while it is still hot and flaky.", skin: "Leave the skin on for the oven or a pan: it protects the fish and goes crisp. It slides off easily once cooked.", stuffing: "", frosting: "", fill: "Salt, pepper, a slice of lemon and a knob of butter, or a spoon of pesto or soy and honey. Keep it simple, the fish does the work." },
    Plan { label: "steak", names: &[Phrase { text: "steak", words: &["steak"] }, Phrase { text: "sirloin", words: &["sirloin"] }, Phrase { text: "ribeye", words: &["ribeye"] }, Phrase { text: "rump steak", words: &["rump", "steak"] }], avoid: &["gammon", "gammon steak", "tuna", "salmon", "fish"], time: "2 to 3 minutes a side for medium rare, 4 a side for medium, plus 5 minutes resting.", temp: "A hot pan or 220C (200C fan) in the oven to finish.", done: "Press it with a finger: springy like the base of your thumb is medium rare, firm is well done. A thermometer reads 50C for rare, 55C medium rare, 60C medium.", keep: "", ahead: "", rest: "Rest it 5 minutes under foil, always: the heat drives the juice to the middle while it cooks, and resting lets it spread back out through the meat. Cut straight away and it ends up on the board.", skin: "Trim any hard fat, but leave a rim of it on: it bastes the steak as it cooks.", stuffing: "", frosting: "", fill: "Salt it generously just before it goes in the pan, then pepper after: pepper burns. A knob of butter and a garlic clove basted over at the end is the restaurant trick." },
    Plan { label: "gammon steak", names: &[Phrase { text: "gammon steak", words: &["gammon", "steak"] }, Phrase { text: "gammon steaks", words: &["gammon", "steaks"] }, Phrase { text: "gammon", words: &["gammon"] }], avoid: &[], time: "4 to 5 minutes a side in a hot pan, or 15 to 20 minutes under the grill, turning once.", temp: "A hot frying pan, or a grill on high.", done: "It is cooked through, not pink: no pink in the middle, and a thermometer reads 70C. It is cured pork, so it wants longer than a beef steak.", keep: "It keeps 2 days cooked, and it is better cold in a sandwich than reheated, which dries it out.", ahead: "", rest: "2 or 3 minutes is enough - there is less juice in it to settle than in beef.", skin: "", stuffing: "", frosting: "", fill: "Nothing more than pepper: it is already salty. A spoon of honey or marmalade in the pan at the end glazes it." },
    Plan { label: "sausages", names: &[Phrase { text: "sausage", words: &["sausage"] }, Phrase { text: "sausages", words: &["sausages"] }], avoid: &[], time: "25 to 30 minutes at 200C (180C fan), turning once.", temp: "200C, or 180C in a fan oven.", done: "They are cooked when they are browned all over and the juices run clear; press one and it should feel firm, not springy.", keep: "They keep 3 days in the fridge and freeze well, cooked or raw.", ahead: "Cook them on the day. They take 25 to 30 minutes and reheat badly, so there is little to gain by doing them early.", rest: "", skin: "Don't prick them: the skin holds the juice in, and pricking is what makes them dry.", stuffing: "", frosting: "", fill: "Nothing inside them: put onion, apple or fennel in the tin beside them, and let the fat that comes out season the mash." },
    Plan { label: "roast potatoes", names: &[Phrase { text: "roast potatoes", words: &["roast", "potatoes"] }, Phrase { text: "roast potato", words: &["roast", "potato"] }, Phrase { text: "roasties", words: &["roasties"] }], avoid: &[], time: "Parboil 8 minutes, then 40 to 45 minutes in the oven, turning once halfway.", temp: "200C, or 180C in a fan oven, in a thin layer of hot oil.", done: "They are ready when the edges are deep gold and crusty; shake the tin and they should rattle.", keep: "They reheat well at 200C for 8 minutes, better than in a microwave.", ahead: "Parboil and rough them up in the morning, keep them in the fridge, and roast them at the last minute.", rest: "", skin: "Leave the skin on if the potatoes are small: it goes crisper than a peeled one.", stuffing: "", frosting: "", fill: "Parboil them, shake them in the pan to rough up the edges, then hot fat or oil, salt and a sprig of rosemary: the rough edges are what go crisp." },
    Plan { label: "cake", names: &[Phrase { text: "cake", words: &["cake"] }, Phrase { text: "sponge", words: &["sponge"] }, Phrase { text: "birthday cake", words: &["birthday", "cake"] }, Phrase { text: "layer cake", words: &["layer", "cake"] }], avoid: &[], time: "A 20cm sponge bakes for 25 to 30 minutes and a loaf tin for 45 to 55; about an hour and a half start to finish once you count mixing and cooling.", temp: "180C, or 160C in a fan oven.", done: "A skewer in the middle comes out clean, and the top springs back when you press it lightly.", keep: "It keeps 3 days in a tin, or freezes for 2 months undecorated.", ahead: "Bake it the day before, cool it completely, wrap it well and fill it on the day: it keeps 3 days in a tin.", rest: "", skin: "", stuffing: "", frosting: "Buttercream or ganache keeps 3 to 4 days in a sealed tub in the fridge, or 2 months in the freezer: bring it back to room temperature and beat it again before you use it. The cake is better filled on the day.", fill: "Butter and sugar creamed first, then eggs a little at a time, then flour folded in gently, and a spoon of milk if the mix is stiff." },
    Plan { label: "curry", names: &[Phrase { text: "curry", words: &["curry"] }, Phrase { text: "tikka", words: &["tikka"] }, Phrase { text: "korma", words: &["korma"] }, Phrase { text: "dhal", words: &["dhal"] }, Phrase { text: "daal", words: &["daal"] }], avoid: &[], time: "35 to 45 minutes from scratch: 10 minutes of frying the onions and spices, then 25 to 30 minutes simmering.", temp: "Medium heat on the hob, 190C (170C fan) if it goes in the oven.", done: "The sauce has darkened and thickened and the oil comes back to the surface; the meat should be tender enough to cut with a spoon.", keep: "It keeps 3 days in the fridge and freezes well for 3 months.", ahead: "It is better made the day before: cool it quickly, keep it in the fridge and reheat it gently with a splash of water.", rest: "", skin: "", stuffing: "", frosting: "", fill: "Start with onion, garlic and ginger, then the spices (cumin, coriander, turmeric, chilli) fried for 30 seconds in the oil, then the meat or veg and a tin of tomatoes or coconut milk." },
    Plan { label: "bread", names: &[Phrase { text: "bread", words: &["bread"] }, Phrase { text: "sourdough", words: &["sourdough"] }, Phrase { text: "loaf", words: &["loaf"] }, Phrase { text: "dough", words: &["dough"] }], avoid: &[], time: "35 to 45 minutes for a large loaf, 20 to 25 for rolls; the first 15 minutes with steam.", temp: "230C, or 210C in a fan oven, with the oven well preheated.", done: "It sounds hollow when you tap the base, and a thermometer reads 95C inside.", keep: "It keeps 3 days in a paper bag; slice and freeze what you won't eat.", ahead: "You can leave the shaped loaf in the fridge overnight and bake it straight from cold, which gives a better flavour.", rest: "", skin: "", stuffing: "", frosting: "", fill: "Flour, water, salt and yeast, and time: a slow rise in the fridge overnight gives more flavour than anything you can add." },
    Plan { label: "chips", names: &[Phrase { text: "chips", words: &["chips"] }, Phrase { text: "fries", words: &["fries"] }, Phrase { text: "oven chips", words: &["oven", "chips"] }, Phrase { text: "frozen chips", words: &["frozen", "chips"] }], avoid: &[], time: "20 to 25 minutes at 200C from frozen, turning once; an air fryer does them in 12 to 15 minutes at 200C. Fresh-cut chips want 30 to 35 minutes.", temp: "200C, or 180C in a fan oven, on a tray with space between them.", done: "Golden at the edges and hollow-sounding when you shake the tray.", keep: "They are only good the day they are cooked: reheat them 5 minutes at 200C, never in a microwave, or they go limp.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Salt after, not before, and a sprig of rosemary or a shake of paprika in the last few minutes. Vinegar at the table." },
    Plan { label: "pie", names: &[Phrase { text: "pie", words: &["pie"] }, Phrase { text: "fruit pie", words: &["fruit", "pie"] }, Phrase { text: "apple pie", words: &["apple", "pie"] }, Phrase { text: "pie dish", words: &["pie", "dish"] }, Phrase { text: "pies", words: &["pies"] }, Phrase { text: "fruit pies", words: &["fruit", "pies"] }], avoid: &[], time: "30 to 35 minutes for a fruit pie with a pastry lid, and 45 minutes if it is a deep one; blind bake an empty case 15 minutes first.", temp: "200C, or 180C in a fan oven.", done: "The pastry is golden and pulls away from the dish a little, and the filling bubbles up through the hole in the middle.", keep: "A fruit pie keeps 2 days in the fridge once it is baked, and reheats at 180C (160C fan) for 15 minutes, which brings the pastry back. Unbaked, it freezes for 3 months: freeze it in the dish, then bake it from frozen at 200C (180C fan) for 20 minutes longer than the recipe says.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "" },
    Plan { label: "shepherd's pie", names: &[Phrase { text: "shepherd's pie", words: &["shepherd's", "pie"] }, Phrase { text: "shepherds pie", words: &["shepherds", "pie"] }, Phrase { text: "shepherd pie", words: &["shepherd", "pie"] }, Phrase { text: "cottage pie", words: &["cottage", "pie"] }, Phrase { text: "chicken pie", words: &["chicken", "pie"] }, Phrase { text: "steak pie", words: &["steak", "pie"] }, Phrase { text: "pot pie", words: &["pot", "pie"] }, Phrase { text: "savoury pie", words: &["savoury", "pie"] }, Phrase { text: "savory pie", words: &["savory", "pie"] }, Phrase { text: "shepherd's pies", words: &["shepherd's", "pies"] }, Phrase { text: "cottage pies", words: &["cottage", "pies"] }, Phrase { text: "chicken pies", words: &["chicken", "pies"] }, Phrase { text: "steak pies", words: &["steak", "pies"] }], avoid: &[], time: "35 to 40 minutes from cold for a shepherd's or cottage pie; a pastry-topped one wants 200C (180C fan) for 30 minutes.", temp: "190C, or 170C in a fan oven.", done: "The top is browned and the filling bubbles at the edges; a skewer in the middle comes out hot.", keep: "It keeps 3 to 4 days in the fridge, covered, and reheats at 180C for 20 minutes or in portions in the microwave. It freezes well for 3 months: freeze it before baking, then cook it from frozen for about an hour, or thaw it overnight first.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "" },
    Plan { label: "scone", names: &[Phrase { text: "scone", words: &["scone"] }, Phrase { text: "scones", words: &["scones"] }, Phrase { text: "fruit scone", words: &["fruit", "scone"] }, Phrase { text: "cheese scone", words: &["cheese", "scone"] }], avoid: &[], time: "12 to 15 minutes, and no longer than that or they go dry.", temp: "220C, or 200C in a fan oven, on a hot floured tray near the top.", done: "They are risen and browned on top, and the sides look dry; a skewer in the middle comes out clean.", keep: "Best eaten the day they are made, warm. They freeze well, split first, and come back in a low oven for 5 minutes.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Rub cold butter into self-raising flour with a pinch of salt, add the milk in one go, and handle the dough as little as you can: cut out the rounds and put them straight in, and do not twist the cutter." },
    Plan { label: "muffin", names: &[Phrase { text: "muffin", words: &["muffin"] }, Phrase { text: "muffins", words: &["muffins"] }, Phrase { text: "blueberry muffin", words: &["blueberry", "muffin"] }, Phrase { text: "chocolate muffin", words: &["chocolate", "muffin"] }], avoid: &[], time: "18 to 22 minutes for a normal-sized tin.", temp: "200C, or 180C in a fan oven.", done: "The tops are domed and spring back when pressed, and a skewer comes out with crumbs rather than wet batter.", keep: "They keep 2 days in a tin and freeze for 2 months.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Melt the butter and mix the wet into the dry in one go, then stop: lumps are right for a muffin. Ten stirs too many is what makes them tough, and frozen berries go in unthawed." },
    Plan { label: "biscuit", names: &[Phrase { text: "biscuit", words: &["biscuit"] }, Phrase { text: "biscuits", words: &["biscuits"] }, Phrase { text: "cookie", words: &["cookie"] }, Phrase { text: "cookies", words: &["cookies"] }, Phrase { text: "shortbread", words: &["shortbread"] }, Phrase { text: "flapjack", words: &["flapjack"] }], avoid: &[], time: "10 to 12 minutes for a drop cookie; shortbread wants 20 to 25 at 160C.", temp: "180C, or 160C in a fan oven, on a lined flat tray.", done: "The edges are set and the middle still looks slightly underdone, which is right: they firm up as they cool on the tray.", keep: "They keep a week in a sealed tin, and freeze for 3 months.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Cream the butter and sugar first, fold the flour in last, and chill the dough 20 minutes so they spread less. Leave 5cm between them on the tray." },
    Plan { label: "meringue", names: &[Phrase { text: "meringue", words: &["meringue"] }, Phrase { text: "meringues", words: &["meringues"] }, Phrase { text: "pavlova", words: &["pavlova"] }], avoid: &[], time: "1 hour to 1 hour 15 for dry meringues, then leave them in the switched-off oven until it is cold.", temp: "100C to 120C, or 90C to 100C in a fan oven, on greaseproof paper.", done: "They lift off the paper cleanly and sound hollow when tapped on the base.", keep: "They keep a week in an airtight tin, and go soft in the fridge.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Bowl and whisk free of grease, no trace of yolk in the whites, and sugar a spoonful at a time once they hold a soft peak: that is what stops them weeping." },
    Plan { label: "yorkshire pudding", names: &[Phrase { text: "yorkshire pudding", words: &["yorkshire", "pudding"] }, Phrase { text: "yorkshire puddings", words: &["yorkshire", "puddings"] }, Phrase { text: "yorkshires", words: &["yorkshires"] }, Phrase { text: "popover", words: &["popover"] }, Phrase { text: "popovers", words: &["popovers"] }], avoid: &[], time: "20 to 25 minutes without opening the door.", temp: "220C, or 200C in a fan oven, with the tin of fat smoking hot first.", done: "They are tall, crisp and brown at the edges; a pale one has not had enough heat or enough fat.", keep: "They freeze for a month and come back at 200C for 5 minutes.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Equal volumes of egg, milk and plain flour, rested half an hour, into a centimetre of smoking oil or dripping: the hot fat is what makes them rise." },
    Plan { label: "roast vegetables", names: &[Phrase { text: "roast vegetables", words: &["roast", "vegetables"] }, Phrase { text: "roast veg", words: &["roast", "veg"] }, Phrase { text: "roasted vegetables", words: &["roasted", "vegetables"] }], avoid: &[], time: "30 to 40 minutes, turning once, with 20 minutes for softer veg like peppers.", temp: "200C, or 180C in a fan oven.", done: "The edges are browned and a knife goes in easily.", keep: "They keep 4 days in the fridge and are good cold in a salad or a wrap.", ahead: "Chop them the night before and keep them in a bowl of cold water in the fridge; drain, oil and roast them as usual.", rest: "", skin: "", stuffing: "", frosting: "", fill: "Oil, salt and pepper is the base; add whole garlic cloves, rosemary or thyme, and a spoon of honey or balsamic for the last 10 minutes." },
    Plan { label: "spag bol", names: &[Phrase { text: "spag bol", words: &["spag", "bol"] }, Phrase { text: "spaghetti bolognese", words: &["spaghetti", "bolognese"] }, Phrase { text: "spaghetti bolognaise", words: &["spaghetti", "bolognaise"] }, Phrase { text: "bolognese", words: &["bolognese"] }, Phrase { text: "bolognaise", words: &["bolognaise"] }, Phrase { text: "bol", words: &["bol"] }], avoid: &[], time: "an hour start to finish, and the sauce is worth the last half of it at a bare simmer with the lid off. Thirty minutes is edible, an hour is good.", temp: "Medium heat on the hob: the mince browns in a dry hot pan before the sauce goes in.", done: "The sauce has darkened and thickened and the fat pools a little at the edge; season it with more salt than feels right and a pinch of sugar.", keep: "Better the next day. It keeps 3 days in the fridge and freezes for 3 months, so a big pot is worth it.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Onion, carrot and celery chopped small and softened first, then mince, tomato puree, tinned tomatoes and a splash of milk or wine; a bay leaf and a pinch of sugar finish it." },
    Plan { label: "lasagne", names: &[Phrase { text: "lasagne", words: &["lasagne"] }, Phrase { text: "lasagna", words: &["lasagna"] }, Phrase { text: "lasagne verdi", words: &["lasagne", "verdi"] }], avoid: &[], time: "35 to 40 minutes in the oven, and the ragu wants 30 to 40 minutes on the hob before you build it.", temp: "180C, or 160C in a fan oven, on the middle shelf.", done: "Bubbling at the edges with the top browned, and a knife through the middle meets no resistance from the pasta; rest it so it cuts cleanly.", keep: "It keeps 3 days in the fridge and freezes in portions for 3 months: reheat covered at 180C for 25 minutes.", ahead: "Assemble it the day before, keep it covered in the fridge and add 5 to 10 minutes in the oven from cold; the ragu alone can be made two days early.", rest: "10 to 15 minutes out of the oven, or it slumps when you cut it.", skin: "", stuffing: "", frosting: "", fill: "A ragu of mince, onion, carrot and tomato cooked down for at least an hour, a bechamel, and parmesan between and on top: the rest is layering." },
    Plan { label: "beef stew", names: &[Phrase { text: "beef stew", words: &["beef", "stew"] }, Phrase { text: "stew", words: &["stew"] }, Phrase { text: "casserole", words: &["casserole"] }, Phrase { text: "hotpot", words: &["hotpot"] }, Phrase { text: "hot pot", words: &["hot", "pot"] }], avoid: &["apple", "apples", "fruit", "prune", "prunes", "rhubarb", "plum", "plums", "pear", "pears", "berry", "berries"], time: "two to two and a half hours at a bare simmer, and longer at a lower heat always beats hotter and shorter.", temp: "150C (130C fan) in the oven with the lid on, or the lowest ring on the hob.", done: "The beef pulls apart with a fork and the liquid has thickened; if it is still tight, another 30 minutes will not hurt it.", keep: "Better the next day, and it keeps 3 days in the fridge or 3 months frozen.", ahead: "It is better the next day, so make it the day before and reheat it gently with a splash of water; it keeps 3 days in the fridge and freezes well.", rest: "", skin: "", stuffing: "", frosting: "", fill: "Onion, carrot, celery and a spoon of tomato puree; add potatoes or dumplings if you want it to be the whole meal, and a splash of Worcestershire or stout for depth." },
    Plan { label: "chilli con carne", names: &[Phrase { text: "chilli con carne", words: &["chilli", "con", "carne"] }, Phrase { text: "chilli", words: &["chilli"] }, Phrase { text: "chili", words: &["chili"] }, Phrase { text: "chile con carne", words: &["chile", "con", "carne"] }], avoid: &["powder", "flakes", "flake", "sauce", "oil", "plant", "plants", "seeds", "seed", "grow", "growing", "grew"], time: "45 minutes to an hour from scratch, and better for longer: brown the mince, then soften the onion and pepper and let the tomatoes and beans go slowly.", temp: "Medium heat on the hob, or 160C (140C fan) in the oven with the lid on.", done: "Darkened and thickened and the fat pools at the edge: taste it and add salt, then a square of dark chocolate if it tastes sharp.", keep: "It keeps 3 days in the fridge and freezes for 3 months, and it is better the next day.", ahead: "", rest: "", skin: "", stuffing: "", frosting: "", fill: "Mince (or beans and mushrooms), onion, garlic, cumin, smoked paprika and chilli, a tin of tomatoes and a tin of kidney beans; a square of dark chocolate at the end rounds it off." },
    Plan { label: "fish pie", names: &[Phrase { text: "fish pie", words: &["fish", "pie"] }, Phrase { text: "fishpie", words: &["fishpie"] }], avoid: &[], time: "35 to 40 minutes at 180C from cold, or 25 minutes if the filling is still warm.", temp: "180C, or 160C in a fan oven.", done: "The sauce bubbles up at the edges and the top is crisp; a knife in the middle comes out hot.", keep: "It keeps 3 to 4 days in the fridge, covered, and reheats at 180C for 20 minutes or in portions in the microwave. It freezes well for 3 months: freeze it unbaked, then cook it from frozen at 180C for about an hour, or thaw it overnight and give it the usual 35 to 40 minutes.", ahead: "", rest: "10 minutes out of the oven, so the sauce settles and it does not run.", skin: "", stuffing: "", frosting: "", fill: "Fish (smoked haddock and a white fish is the classic), a white sauce made with the milk the fish was poached in, and mashed potato on top with a little mustard and cheese." },
    Plan { label: "pasta bake", names: &[Phrase { text: "pasta bake", words: &["pasta", "bake"] }, Phrase { text: "baked pasta", words: &["baked", "pasta"] }, Phrase { text: "tuna bake", words: &["tuna", "bake"] }, Phrase { text: "macaroni cheese bake", words: &["macaroni", "cheese", "bake"] }], avoid: &[], time: "25 to 30 minutes at 200C, or 20 minutes if the pasta and sauce are still hot.", temp: "200C, or 180C in a fan oven.", done: "The cheese is browned and the sauce bubbles at the edges; cook the pasta 2 minutes short of the packet first, or it goes soft in the oven.", keep: "It keeps 3 days in the fridge and reheats covered at 180C for 20 minutes.", ahead: "Boil the pasta and make the sauce the day before, mix and cover it in the fridge, then bake it from cold with 10 minutes extra; baked and cooled it reheats covered at 180C for 20 minutes.", rest: "", skin: "", stuffing: "", frosting: "", fill: "A tomato sauce with garlic and basil, cooked pasta, and mozzarella or cheddar on top; add bacon, courgette or spinach to the sauce if you have them." },
    Plan { label: "sunday roast", names: &[Phrase { text: "sunday roast", words: &["sunday", "roast"] }, Phrase { text: "roast dinner", words: &["roast", "dinner"] }, Phrase { text: "roast lunch", words: &["roast", "lunch"] }, Phrase { text: "a roast", words: &["a", "roast"] }], avoid: &["vegetables", "veg", "potatoes", "potato", "chicken", "beef", "lamb", "pork", "turkey", "duck", "nuts", "chestnuts", "coffee", "beans", "peppers", "tomatoes", "onions", "parsnips", "carrots", "garlic"], time: "about 1 hour 40 at 190C for a 2kg joint or bird.", temp: "190C (170C fan) for a joint or a bird, and the potatoes go up to 200C once the meat is out and resting.", done: "74C in the thickest part of a chicken thigh, or 60C for beef you want pink.", keep: "Leftovers keep 3 days, and the bones make the gravy or a stock.", ahead: "Prep the night before: parboil and rough up the potatoes and keep them in the fridge, and peel the veg into a bowl of cold water. The meat goes in on the day, because that is the part that wants the oven.", rest: "15 to 20 minutes under foil while the potatoes finish and the gravy is made, which is what makes the timings work.", skin: "", stuffing: "", frosting: "", fill: "A joint, potatoes parboiled and roasted in hot fat, and two veg: carrots or parsnips in the oven, greens on the hob. Gravy from the tin juices." },
];
